package app.studyforge.mobile;
import org.junit.Test;
import org.json.*;
import static org.junit.Assert.*;
public class StudyGeneratorTest {
 JSONObject badDraft()throws Exception{JSONObject draft=CoreTest.result();draft.put("directives",Json.array(Json.object("kind","remember","title","외울 것","text","외우세요","source_id","s1","page",1,"quote","틸라코이드 막에서 ATP와 NADPH를 생성한다.")));return draft;}
 static JSONObject review(int count)throws Exception{JSONArray checks=new JSONArray();for(int i=0;i<count;i++)checks.put(Json.object("index",i,"answer",true,"evidence",true,"scope",true,"options",true,"wording",true,"patch",new JSONObject()));return Json.object("checks",checks,"document_patch",new JSONObject(),"review_notes",Json.array("모든 문항의 정답·원본 근거·범위·보기·질문을 검수함"));}
 @Test public void scheduledReviewRepairsInvalidDraftBeforeFinalValidation()throws Exception{int[] calls={0};JSONObject result=new StudyGenerator((request,progress)->{if(calls[0]++==0)return badDraft().toString();assertTrue(request.toString().contains("초안 자동 검증 오류"));assertTrue(request.toString().contains("교수님 학습 지시는 수업 자료의 직접 근거가 필요합니다."));return review(1).put("document_patch",Json.object("directives",new JSONArray())).toString();}).generate(Json.object("generationMode","concept"),CoreTest.sources(),1,"m",p->{});assertEquals(2,calls[0]);assertEquals(2,result.getJSONObject("audit").getInt("passes"));assertEquals(0,result.getJSONArray("directives").length());assertEquals(1,result.getJSONArray("questions").length());}
 @Test public void invalidFinalReviewIsNeverReturnedAsALearningRoom()throws Exception{int[] calls={0};assertThrows(Exception.class,()->new StudyGenerator((request,progress)->calls[0]++==0?badDraft().toString():review(1).toString()).generate(Json.object("generationMode","concept"),CoreTest.sources(),1,"m",p->{}));assertEquals(2,calls[0]);}
 @Test public void explicitInsufficientEvidenceDoesNotTriggerFabrication()throws Exception{int[] calls={0};assertThrows(Exception.class,()->new StudyGenerator((request,progress)->{calls[0]++;return Json.object("error","근거 없음").toString();}).generate(Json.object("generationMode","concept"),CoreTest.sources(),1,"m",p->{}));assertEquals(1,calls[0]);}
 @Test public void unchangedReviewPreservesFullContentWithoutRewriting()throws Exception{JSONObject draft=CoreTest.result(),result=GenerationReview.apply(draft,review(1));assertEquals(draft.getJSONArray("questions").toString(),result.getJSONArray("questions").toString());assertEquals(draft.getJSONArray("summary").toString(),result.getJSONArray("summary").toString());assertFalse(draft.has("review_notes"));assertTrue(review(1).toString().length()<draft.toString().length()/2);}
 @Test public void reviewCannotSkipDuplicateOrInventQuestionIndices()throws Exception{assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),review(0)));JSONObject duplicate=review(2);duplicate.getJSONArray("checks").getJSONObject(1).put("index",0);JSONObject draft=CoreTest.result();draft.getJSONArray("questions").put(Json.copy(draft.getJSONArray("questions").getJSONObject(0)));assertThrows(Exception.class,()->GenerationReview.apply(draft,duplicate));JSONObject outside=review(1);outside.getJSONArray("checks").getJSONObject(0).put("index",1);assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),outside));JSONObject fraction=review(1);fraction.getJSONArray("checks").getJSONObject(0).put("index",0.5);assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),fraction));}
 @Test public void everyQualityCheckMustExplicitlyPass()throws Exception{for(String key:new String[]{"answer","evidence","scope","options","wording"}){JSONObject fail=review(1);fail.getJSONArray("checks").getJSONObject(0).put(key,false);assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),fail));JSONObject missing=review(1);missing.getJSONArray("checks").getJSONObject(0).remove(key);assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),missing));}}
 @Test public void patchesCannotMutateIdsSourcesOrQuestionCount()throws Exception{for(String key:new String[]{"id","sources","questions","audit","answers"}){JSONObject bad=review(1);bad.getJSONObject("document_patch").put(key,"bad");assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),bad));}JSONObject bad=review(1);bad.getJSONArray("checks").getJSONObject(0).getJSONObject("patch").put("id","bad");assertThrows(Exception.class,()->GenerationReview.apply(CoreTest.result(),bad));}
 @Test public void patchedAnswerAndEvidenceStillRequireFullValidation()throws Exception{for(JSONObject patch:new JSONObject[]{Json.object("answer",5),Json.object("options",Json.array("a","a","b","c","d")),Json.object("citations",Json.array(Json.object("source_id","s1","page",99,"quote","없음")))}){int[] calls={0};assertThrows(Exception.class,()->new StudyGenerator((r,p)->{if(calls[0]++==0)return CoreTest.result().toString();JSONObject review=review(1);review.getJSONArray("checks").getJSONObject(0).put("patch",patch);return review.toString();}).generate(new JSONObject(),CoreTest.sources(),1,"m",p->{}));assertEquals(2,calls[0]);}}
 @Test public void preciseWordingPatchPreservesOtherQuestionFields()throws Exception{JSONObject r=review(1);r.getJSONArray("checks").getJSONObject(0).put("patch",Json.object("stem","빛에너지가 화학에너지로 전환되는 장소는?"));JSONObject result=GenerationReview.apply(CoreTest.result(),r);assertEquals("빛에너지가 화학에너지로 전환되는 장소는?",result.getJSONArray("questions").getJSONObject(0).getString("stem"));assertEquals(CoreTest.result().getJSONArray("questions").getJSONObject(0).getJSONArray("option_explanations").toString(),result.getJSONArray("questions").getJSONObject(0).getJSONArray("option_explanations").toString());}
 @Test public void preparedConceptSummaryIsReusedVerbatimAndStillReviewed()throws Exception{JSONArray sources=CoreTest.sources();sources.getJSONObject(0).put("evidence",Json.array(Json.object("page",1,"quote",sources.getJSONObject(0).getString("text"),"text","기존 분석 상세 내용","topic","명반응")));int[] calls={0};JSONObject result=new StudyGenerator((r,p)->{if(calls[0]++==0){assertTrue(r.getString("instructions").contains("summary와 overview를 생략"));JSONObject draft=CoreTest.result();draft.remove("summary");return draft.toString();}assertTrue(r.toString().contains("기존 분석 상세 내용"));return review(1).toString();}).generate(Json.object("generationMode","concept","wholeBookOverview","저장된 전체 분석"),sources,1,"selected-model",p->{});assertEquals("기존 분석 상세 내용",result.getJSONArray("summary").getJSONObject(0).getString("text"));assertEquals("저장된 전체 분석",result.getString("overview"));assertTrue(result.getJSONObject("audit").getBoolean("summaryReused"));assertEquals("selected-model",result.getString("model"));assertTrue(result.getJSONObject("audit").getLong("draftMs")>=0);}
 @Test public void originalModeStillPreservesAnswerKeyAndCompleteOriginal()throws Exception{JSONArray sources=CoreTest.sources();sources.getJSONObject(0).put("role","workbook");JSONObject draft=CoreTest.result();JSONObject question=draft.getJSONArray("questions").getJSONObject(0);question.put("kind","original").put("answer_citation",Json.copy(question.getJSONArray("citations").getJSONObject(0)));int[] calls={0};JSONObject result=new StudyGenerator((r,p)->calls[0]++==0?draft.toString():review(1).toString()).generate(Json.object("generationMode","original"),sources,1,"m",p->{});assertEquals(question.getString("stem"),result.getJSONArray("questions").getJSONObject(0).getString("stem"));assertEquals(question.getJSONArray("options").toString(),result.getJSONArray("questions").getJSONObject(0).getJSONArray("options").toString());assertTrue(result.getJSONArray("questions").getJSONObject(0).has("answer_citation"));assertFalse(result.getJSONObject("audit").getBoolean("summaryReused"));}
 @Test public void pastExpansionKeepsProvenanceCoverageAndMaximumCount()throws Exception{int[] calls={0};JSONObject result=new StudyGenerator((r,p)->calls[0]++==0?PastExpansionTest.result().toString():review(1).toString()).generate(Json.object("generationMode",PastExpansion.MODE),PastExpansionTest.sources(),5,"m",p->{});assertEquals(1,result.getJSONArray("questions").length());assertEquals(PastExpansionTest.result().getJSONArray("past_coverage").toString(),result.getJSONArray("past_coverage").toString());assertEquals("past_reconstructed",result.getJSONArray("questions").getJSONObject(0).getString("kind"));assertEquals("medium",result.getJSONArray("questions").getJSONObject(0).getJSONObject("past").getString("confidence"));assertEquals(2,calls[0]);}
}
